41	    /**
42	     * Converts the supplied telephone to its canonical E.164 representation.
43	     *
44	     * @param telephone the raw telephone as submitted
45	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
46	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
47	     */
48	    public static String normalize(String telephone) {
49	        String trimmed = telephone == null ? "" : telephone.trim();
50	        boolean hasCountryCode = trimmed.startsWith("+");
51	        String digits = NON_DIGIT.matcher(trimmed).replaceAll("");
52	
53	        String national = digits;
54	        if (!hasCountryCode && national.startsWith("0")) {
55	            national = national.substring(1);
56	        }
57	        String prefix = hasCountryCode ? "+" : DEFAULT_COUNTRY_CODE;
58	        String e164 = prefix + national;
59	
60	        int digitCount = e164.length() - 1;
61	        if (digitCount < MIN_DIGITS || digitCount > MAX_DIGITS) {
62	            throw new InvalidTelephoneException(telephone);
