17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.rest.validation.DuplicateHouseholdException;
39	import org.springframework.samples.petclinic.rest.validation.DuplicateTelephoneException;
40	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
41	import org.springframework.samples.petclinic.rest.validation.MissingOwnerFieldsException;
42	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
43	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    public OwnerRestControllerV1(ClinicService clinicService,
71	                                 OwnerMapper ownerMapper,
72	                                 PetMapper petMapper,
73	                                 VisitMapper visitMapper) {
74	        this.clinicService = clinicService;
75	        this.ownerMapper = ownerMapper;
76	        this.petMapper = petMapper;
77	        this.visitMapper = visitMapper;
78	    }
79	
80	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
81	    @Override
82	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
83	        Collection<Owner> owners;
84	        if (lastName != null) {
85	            owners = this.clinicService.findOwnerByLastName(lastName);
86	        } else {
87	            owners = this.clinicService.findAllOwners();
88	        }
89	        if (owners.isEmpty()) {
90	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
91	        }
92	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
98	        Owner owner = this.clinicService.findOwnerById(ownerId);
99	        if (owner == null) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        List<String> missingFields = OwnerFieldsValidator.findMissingFields(ownerFieldsDto);
109	        if (!missingFields.isEmpty()) {
110	            throw new MissingOwnerFieldsException(missingFields);
111	        }
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        String telephone = TelephoneNormalizer.normalize(owner.getTelephone());
115	        if (!this.clinicService.findOwnerByTelephone(telephone).isEmpty()) {
116	            throw new DuplicateTelephoneException(telephone);
117	        }
118	        Collection<Owner> household =
119	            this.clinicService.findOwnersInHousehold(owner.getLastName(), owner.getAddress());
120	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
121	        if (!household.isEmpty() && !sharesHousehold) {
122	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
123	        }
124	        owner.setTelephone(telephone);
125	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
126	        if (sharesHousehold) {
127	            this.clinicService.joinHousehold(owner, household);
128	        }
129	        this.clinicService.saveOwner(owner);
130	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
131	        headers.setLocation(UriComponentsBuilder.newInstance()
132	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
133	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
139	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
140	        if (currentOwner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        currentOwner.setAddress(ownerFieldsDto.getAddress());
144	        currentOwner.setCity(ownerFieldsDto.getCity());
145	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
146	        currentOwner.setLastName(ownerFieldsDto.getLastName());
147	        currentOwner.setTelephone(TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
148	        currentOwner.setEmail(EmailNormalizer.normalize(ownerFieldsDto.getEmail()));
149	        this.clinicService.saveOwner(currentOwner);
150	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
151	    }
152	
153	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
154	    @Transactional
155	    @Override
156	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
157	        Owner owner = this.clinicService.findOwnerById(ownerId);
158	        if (owner == null) {
159	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
160	        }
161	        this.clinicService.deleteOwner(owner);
162	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
168	        Owner owner = this.clinicService.findOwnerById(ownerId);
169	        if (owner == null) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        HttpHeaders headers = new HttpHeaders();
173	        Pet pet = petMapper.toPet(petFieldsDto);
174	        owner.setId(ownerId);
175	        pet.setOwner(owner);
176	        pet.getType().setName(null);
177	        this.clinicService.savePet(pet);
178	        PetDto petDto = petMapper.toPetDto(pet);
179	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
180	            .buildAndExpand(pet.getId()).toUri());
181	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
187	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
188	        if (currentOwner != null) {
189	            Pet currentPet = this.clinicService.findPetById(petId);
190	            if (currentPet != null) {
191	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
192	                currentPet.setName(petFieldsDto.getName());
193	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
194	                this.clinicService.savePet(currentPet);
195	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
196	            }
197	        }
198	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
199	    }
200	
201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Override
203	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
204	        HttpHeaders headers = new HttpHeaders();
205	        Visit visit = visitMapper.toVisit(visitFieldsDto);
206	        Pet pet = new Pet();
207	        pet.setId(petId);
208	        visit.setPet(pet);
209	        this.clinicService.saveVisit(visit);
210	        VisitDto visitDto = visitMapper.toVisitDto(visit);
211	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
212	            .buildAndExpand(visit.getId()).toUri());
213	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
214	    }
215	
216	
217	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
218	    @Override
219	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
220	        Owner owner = this.clinicService.findOwnerById(ownerId);
221	        if (owner != null) {
222	            Pet pet = owner.getPet(petId);
223	            if (pet != null) {
224	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
225	            }
226	        }
227	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
228	    }
229	}
